#include "unity.h"
#include "mock_runtime_clock.h"
#include "motion_processor.h"
#include "app_config.h"

#include <stdint.h>

static int16_t raw_count_for_millig(int32_t millig)
{
    int64_t magnitude = (millig < 0) ? -(int64_t)millig : (int64_t)millig;
    int64_t raw_magnitude =
        (magnitude * (int64_t)APP_MOTION_SENSITIVITY_LSB_PER_G + 999) / 1000;
    return (int16_t)((millig < 0) ? -raw_magnitude : raw_magnitude);
}

void setUp(void)
{
    runtime_clock_now_ms_IgnoreAndReturn(0U);
    runtime_clock_delay_ms_Ignore();
}

void tearDown(void)
{
}

void test_FR_012_01(void)
{
    motion_sample_t sample;
    motion_processor_status_t status;

    /* Collect one calibration sample, then complete calibration at 1000 ms. */
    status = motion_processor_process(0, 0, 8192, 0U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_CALIBRATING, status);
    status = motion_processor_process(0, 0, 8192, APP_MOTION_CALIBRATION_DURATION_MS, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);

    /* Each threshold is exercised independently within a fresh event window. */
    status = motion_processor_process(
        raw_count_for_millig((int32_t)APP_MOTION_WIDE_TURN_THRESHOLD_MILLIG),
        0, 8192, 1001U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_WIDE_TURN, sample.event);

    (void)motion_processor_process(0, 0, 8192, 1100U, &sample);
    status = motion_processor_process(
        0,
        raw_count_for_millig(-(int32_t)APP_MOTION_SUDDEN_BRAKING_THRESHOLD_MILLIG),
        8192, 1101U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_SUDDEN_BRAKING, sample.event);

    (void)motion_processor_process(0, 0, 8192, 1200U, &sample);
    status = motion_processor_process(
        0, 0,
        raw_count_for_millig(1000 + (int32_t)APP_MOTION_SPEED_BREAKER_THRESHOLD_MILLIG),
        1201U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_UNSEEN_SPEED_BREAKER, sample.event);

    (void)motion_processor_process(0, 0, 8192, 1300U, &sample);
    status = motion_processor_process(
        0,
        raw_count_for_millig((int32_t)APP_MOTION_SPEEDING_THRESHOLD_MILLIG),
        8192, 1301U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_SPEEDING, sample.event);
}
